package score

// CalcResult computes the weighted score.
func CalcResult(raw int, weight float64) float64 {
	return float64(raw) * weight
}

func Grade(raw int) string {
	s := CalcResult(raw, 1.0)
	if s >= 90 {
		return "A"
	} else if s >= 80 {
		return "B"
	} else if s >= 70 {
		return "C"
	}
	return "F"
}

