package score

import "testing"

func TestComputeScore(t *testing.T) {
	got := ComputeScore(50, 2.0)
	if got != 100.0 {
		t.Errorf("ComputeScore(50, 2.0) = %f, want 100.0", got)
	}
}

func TestGrade(t *testing.T) {
	if Grade(95) != "A" {
		t.Error("expected A for raw=95")
	}
	if Grade(50) != "F" {
		t.Error("expected F for raw=50")
	}
}

func TestReport(t *testing.T) {
	got := Report(10, 3.0)
	if got != "Score: 30.0" {
		t.Errorf("Report(10, 3.0) = %q, want 'Score: 30.0'", got)
	}
}
